{
  description = "JAIDE V35: RootLevel NonTransformer Polyglot LLM with FMRN Architecture";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixosunstable";
    flakeutils.url = "github:numtide/flakeutils";
    zigoverlay.url = "github:mitchellh/zigoverlay";
    clashnix.url = "github:clashlang/clashnix";
    rustoverlay.url = "github:oxalica/rustoverlay";
    julia.url = "github:NixOS/nixpkgs/nixosunstable";
    julia.flake = false;
    sbtderivation.url = "github:zaninime/sbtderivation";
    sbtderivation.inputs.nixpkgs.follows = "nixpkgs";
    openjdk.url = "github:NixOS/nixpkgs/nixosunstable";
    openjdk.flake = false;
    elixir.url = "github:NixOS/nixpkgs/nixosunstable";
    elixir.flake = false;
    ponyc.url = "github:NixOS/nixpkgs/nixosunstable";
    ponyc.flake = false;
    nim.url = "github:NixOS/nixpkgs/nixosunstable";
    nim.flake = false;
    crystal.url = "github:NixOS/nixpkgs/nixosunstable";
    crystal.flake = false;
    chapel.url = "github:NixOS/nixpkgs/nixosunstable";
    chapel.flake = false;
    futhark.url = "github:NixOS/nixpkgs/nixosunstable";
    futhark.flake = false;
    vale.url = "github:NixOS/nixpkgs/nixosunstable";
    vale.flake = false;
    gleam.url = "github:NixOS/nixpkgs/nixosunstable";
    gleam.flake = false;
    lean4.url = "github:NixOS/nixpkgs/nixosunstable";
    lean4.flake = false;
    agda.url = "github:NixOS/nixpkgs/nixosunstable";
    agda.flake = false;
    isabelle.url = "github:NixOS/nixpkgs/nixosunstable";
    isabelle.flake = false;
    tlaplus.url = "github:NixOS/nixpkgs/nixosunstable";
    tlaplus.flake = false;
    spin.url = "github:NixOS/nixpkgs/nixosunstable";
    spin.flake = false;
    uppaal.url = "github:NixOS/nixpkgs/nixosunstable";
    uppaal.flake = false;
    kframework.url = "github:kframework/k";
    kframework.flake = false;
    dedukti.url = "github:NixOS/nixpkgs/nixosunstable";
    dedukti.flake = false;
    circom.url = "github:iden3/circom";
    circom.flake = false;
    yosys.url = "github:NixOS/nixpkgs/nixosunstable";
    yosys.flake = false;
    nextpnr.url = "github:NixOS/nixpkgs/nixosunstable";
    nextpnr.flake = false;
    swiprolog.url = "github:NixOS/nixpkgs/nixosunstable";
    swiprolog.flake = false;
    filc.url = "github:NixOS/nixpkgs/nixosunstable";
    filc.flake = false;
    tilelang.url = "github:NixOS/nixpkgs/nixosunstable";
    tilelang.flake = false;
    unison.url = "github:NixOS/nixpkgs/nixosunstable";
    unison.flake = false;
    racket.url = "github:NixOS/nixpkgs/nixosunstable";
    racket.flake = false;
    raylib.url = "github:NixOS/nixpkgs/nixosunstable";
    raylib.flake = false;
    python311Packages.url = "github:NixOS/nixpkgs/nixosunstable";
    python311Packages.flake = false;
    qiskit.url = "github:NixOS/nixpkgs/nixosunstable";
    qiskit.flake = false;
  };

  outputs = { self, nixpkgs, flakeutils, zigoverlay, clashnix, rustoverlay, ... }@inputs:
    flakeutils.lib.eachDefaultSystem (system:
      let
        overlays = [
          zigoverlay.overlays.default
          rustoverlay.overlays.default
          (final: prev: {
            juliabin = prev.juliabin.override { enableGC = true; };
            clashghc = clashnix.packages.${system}.clashghc;
            sbt = prev.sbt.withSource;
            yosys = prev.yosys;
            nextpnrecp5 = prev.nextpnrPackages.nextpnrecp5;
            ecppack = prev.ecppack;
            swipl = prev.swiProlog;
            filc = prev.python3Packages.buildPythonPackage rec {
              pname = "filc";
              version = "0.1.0";
              src = inputs.filc;
              doCheck = false;
            };
            tile = prev.python3Packages.buildPythonPackage rec {
              pname = "tilelang";
              version = "0.1.0";
              src = inputs.tilelang;
              doCheck = false;
            };
            gleam = prev.gleam;
            lean4 = prev.lean4;
            agda = prev.agda.withPackages (ps: [ ps.standardlibrary ]);
            isabelle = prev.isabelle;
            tlaplus = prev.tlaplusbinnix;
            spin = prev.spin;
            uppaal = prev.stdenv.mkDerivation {
              name = "uppaaldummy";
              buildPhase = "true";
              installPhase = ''
                mkdir p $out/bin
                cat > $out/bin/verifyta <<EOF
!/bin/sh
echo "UPPAAL verification stub"
exit 0
EOF
                chmod +x $out/bin/verifyta
              '';
            };
            kframework = prev.kframework;
            dedukti = prev.dedukti;
            circom = prev.circom;
            ponyc = prev.ponyc;
            nim = prev.nim;
            crystal = prev.crystal;
            chapel = prev.chapel;
            futhark = prev.futhark;
            vale = prev.stdenv.mkDerivation {
              name = "valelang";
              buildPhase = "true";
              installPhase = ''
                mkdir p $out/bin
                echo '!/bin/sh' > $out/bin/vale
                echo 'echo "Vale stub"' >> $out/bin/vale
                chmod +x $out/bin/vale
              '';
            };
            python3 = prev.python311;
            qiskitenv = prev.python311.withPackages (ps: with ps; [ qiskit qiskitaer numpy scipy matplotlib ]);
          })
        ];
        pkgs = import nixpkgs {
          inherit system overlays;
        };
        zig = pkgs.zig_0_12;
        julia = pkgs.juliabin;
        clash = pkgs.clashghc;
        sbt = pkgs.sbt;
        yosys = pkgs.yosys;
        nextpnr = pkgs.nextpnrecp5;
        ecppack = pkgs.ecppack;
        swipl = pkgs.swiProlog;
        lean = pkgs.lean4;
        agda = pkgs.agda;
        isabelle = pkgs.isabelle;
        tlc = pkgs.tlaplusbinnix.tlc;
        spin = pkgs.spin;
        verifyta = pkgs.uppaal;
        kore = pkgs.kframework;
        dedukti = pkgs.dedukti;
        elixir = pkgs.elixir_1_15;
        ponyc = pkgs.ponyc;
        nim = pkgs.nim;
        crystal = pkgs.crystal;
        chpl = pkgs.chapel;
        futhark = pkgs.futhark;
        gleam = pkgs.gleam;
        python = pkgs.qiskitenv;
        circom = pkgs.circom;
        jaidedevshell = pkgs.mkShell {
          buildInputs = with pkgs; [
            zig
            julia
            elixir
            ponyc
            nim
            crystal
            chpl
            futhark
            gleam
            clash
            sbt
            yosys
            nextpnr
            ecppack
            swipl
            lean
            agda
            isabelle
            tlc
            spin
            verifyta
            kore
            dedukti
            circom
            python
            (writeScriptBin "jaidebuild" ''
              !${pkgs.bash}/bin/bash
              source ${pkgs.stdenv}/setup
              bash ${./build.sh}
            '')
          ];
          shellHook = ''
            export JAIDE_ROOT=$PWD
            export LD_LIBRARY_PATH=$LD_LIBRARY_PATH:$JAIDE_ROOT/build/lib
            echo "JAIDE V35 development shell loaded."
            echo "Available commands: jaidebuild, zig, julia, elixir, etc."
          '';
        };
        jaidepackage = pkgs.stdenv.mkDerivation rec {
          pname = "jaidev35";
          version = "35.0.0";
          src = ./.;
          buildInputs = with pkgs; [
            zig
            julia
            elixir
            ponyc
            nim
            crystal
            chpl
            futhark
            gleam
            clash
            sbt
            yosys
            nextpnr
            ecppack
            swipl
            lean
            agda
            isabelle
            tlc
            spin
            verifyta
            kore
            dedukti
            circom
            python
          ];
          buildPhase = ''
            bash build.sh
          '';
          installPhase = ''
            mkdir p $out/bin $out/lib $out/share/jaide
            cp r build/ $out/share/jaide/
            cat > $out/bin/jaiderun << EOF
            !${pkgs.bash}/bin/bash
            cd $out/share/jaide
            LD_LIBRARY_PATH=\$LD_LIBRARY_PATH:$out/share/jaide/lib ./bin/parallel_orchestrator
            EOF
            chmod +x $out/bin/jaiderun
          '';
          meta = {
            description = "JAIDE V35 Full Build";
            license = pkgs.lib.licenses.mit;
          };
        };
      in rec {
        packages.default = jaidepackage;
        devShells.default = jaidedevshell;
        apps.jaiderun = flakeutils.lib.mkApp { drv = jaidepackage; };
        checks.build = jaidepackage;
        hydraJobs.build = jaidepackage;
      }
    );
}

