            swipl
            lean
            agda
            isabelle
            tlaplus
            spin
            dedukti
            circom
            python
            (writeScriptBin "jaidebuild" ''
!${pkgs.bash}/bin/bash
set euo pipefail
bash ${./build.sh}
'')
          ];
          shellHook = ''
            export JAIDE_ROOT=$PWD
            export LD_LIBRARY_PATH=$LD_LIBRARY_PATH:$JAIDE_ROOT/build/lib
            echo "JAIDE V35 development shell loaded."
            echo "Available commands: jaidebuild, zig, julia, elixir, etc."
          '';
        };
        jaidepackage = pkgs.stdenv.mkDerivation rec {
          pname = "jaidev35";
          version = "35.0.0";
          src = ./.;
          buildInputs = with pkgs; [
            zig
            julia
            elixir
            ponyc
            nim
            crystal
            chpl
            futhark
            gleam
            clash
            sbt
            yosys
            nextpnr
            ecppack
            swipl
            lean
            agda
            isabelle
            tlaplus
            spin
            dedukti
            circom
            python
          ];
          buildPhase = ''
            bash build.sh
          '';
          installPhase = ''
            mkdir p $out/bin $out/lib $out/share/jaide
            cp r build/ $out/share/jaide/
            cat > $out/bin/jaiderun <<EOF
!${pkgs.bash}/bin/bash
set euo pipefail
cd $out/share/jaide
LD_LIBRARY_PATH=\$LD_LIBRARY_PATH:$out/share/jaide/lib ./bin/parallel_orchestrator
EOF
            chmod +x $out/bin/jaiderun
          '';
          meta = {
            description = "JAIDE V35 Full Build";
            license = pkgs.lib.licenses.mit;
          };
        };
      in rec {
        packages.default = jaidepackage;
        devShells.default = jaidedevshell;
        apps.jaiderun = {
          type = "app";
          program = "${jaidepackage}/bin/jaiderun";
        };
        checks.build = jaidepackage;
        hydraJobs.build = jaidepackage;
      }
    );
}
